import{_ as a,o as e,c as o,ag as d}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"补充杂项","description":"","frontmatter":{"title":"补充杂项"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/补充杂项.md","filePath":"综合知识/系统基础/操作系统/补充杂项.md","lastUpdated":null}'),r={name:"综合知识/系统基础/操作系统/补充杂项.md"};function l(i,t,n,h,s,c){return e(),o("div",null,[...t[0]||(t[0]=[d('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] HTTPS vs HTTP</li><li>[ ] 工作流描述工具</li><li>[ ] 数据资产特征</li><li>[ ] 数据库类型</li><li>[ ] Linux 常用命令</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="https-vs-http" tabindex="-1">HTTPS vs HTTP <a class="header-anchor" href="#https-vs-http" aria-label="Permalink to &quot;HTTPS vs HTTP&quot;">​</a></h3><blockquote><p>🎯 一句话结论：HTTPS 使用加密传输，默认端口 443；HTTP 默认端口 80。电子支付类网站<strong>必须使用 HTTPS</strong>。</p></blockquote><h3 id="工作流描述工具" tabindex="-1">工作流描述工具 <a class="header-anchor" href="#工作流描述工具" aria-label="Permalink to &quot;工作流描述工具&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>用例图</strong>不可用来描述工作流。可用的有：活动图、BPMN、Petri-Net。</p></blockquote><p>工作流表示业务过程模型，通常用图形描述。用例图用于描述系统功能需求，不表示业务流程。</p><h3 id="数据资产特征" tabindex="-1">数据资产特征 <a class="header-anchor" href="#数据资产特征" aria-label="Permalink to &quot;数据资产特征&quot;">​</a></h3><blockquote><p>🎯 一句话结论：数据资产四大特征 — <strong>可增值、可共享、可控制、可量化</strong>。</p></blockquote><p>记忆口诀：&quot;增值共享，控制量化&quot;。不可测试、不可维护。</p><h3 id="数据库类型" tabindex="-1">数据库类型 <a class="header-anchor" href="#数据库类型" aria-label="Permalink to &quot;数据库类型&quot;">​</a></h3><blockquote><p>🎯 一句话结论：键值数据库存储键值对；文档数据库存 JSON/XML/BSON（不止纯文本）；早期三大类型是层次式、网络式、关系型。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>存储格式</th><th>备注</th></tr></thead><tbody><tr><td>键值数据库</td><td>键值对集合</td><td>NoSQL</td></tr><tr><td>文档数据库</td><td>JSON/XML/BSON</td><td>⚠️ 不止纯文本</td></tr><tr><td>关系型数据库</td><td>二维表</td><td>—</td></tr></tbody></table><p>早期数据库三种主要类型：<strong>层次式、网络式、关系型</strong>。键值数据库属于 NoSQL，不是早期三大类型。</p><h3 id="linux-常用命令" tabindex="-1">Linux 常用命令 <a class="header-anchor" href="#linux-常用命令" aria-label="Permalink to &quot;Linux 常用命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td><code>ping</code></td><td>测试主机可达性</td></tr><tr><td><code>ifconfig</code></td><td>查看网络配置</td></tr><tr><td><code>netstat</code></td><td>查看网络状态</td></tr><tr><td><code>uname</code></td><td>查看系统信息</td></tr></tbody></table>',17)])])}const p=a(r,[["render",l]]);export{b as __pageData,p as default};
